import {b,fmt,clamp,shells,heating,work,buoyancy,pendulum,falling} from '../math.js';
import {C,reflect,read,particles,molecule,atom,cell,neuron,plants,organelles} from '../scene-utils.js';
export default ({g,t,p})=>{let tau=t%10,u=2,a=p[0],v=u+a*tau,s=u*tau+.5*a*tau*tau;g.line([-1.4,.4,0],[1.4,.4,0]);g.box(-1.3+2.6*s/270,.15,0,.16,.14,.15,C.gold,{solid:true});let pts=Array.from({length:41},(_,i)=>{let q=tau*i/40;return[q,u+a*q]});g.plot({title:b('Velocity (m/s) vs time (s)','वेग (m/s) बनाम समय (s)'),xMax:10,yMax:52,xLabel:'s',points:pts,marker:[tau,v],area:true});return[read('Initial velocity','प्रारम्भिक वेग',u,'m/s'),read('Current velocity','वर्तमान वेग',fmt(v),'m/s'),read('Area = displacement','क्षेत्रफल = विस्थापन',fmt(s),'m')];};
